@contextlib.contextmanager
def _stderr_sidecar(path: Path) -> Generator[None, None, None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        original = sys.stderr
        class _Tee:
            def write(self, data: str) -> int:
                original.write(data)
                handle.write(data)
                return len(data)

            def flush(self) -> None:
                original.flush()

